#include <utf8proc.h>
#include <string.h>

int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size)
{
    if(size < 1) return 0;

    /* Avoid timeout with long inputs */
    if(size > (64 * 1024)) return 0;

    if(data[size-1] != '\0') return 0;

    const uint8_t* ptr = data;
    utf8proc_int32_t c = 0, c_prev = 0, state = 0;
    unsigned int options;
    utf8proc_ssize_t ret, bytes = 0;
    utf8proc_uint8_t *str = NULL;
    size_t len = strlen((const char*)data);

    while(bytes != len)
    {
        ret = utf8proc_iterate(ptr, -1, &c);

        if(ret < 0 || ret == 0) break;

        bytes += ret;
        ptr += ret;

        utf8proc_tolower(c);
        utf8proc_toupper(c);
        utf8proc_totitle(c);
        utf8proc_islower(c);
        utf8proc_isupper(c);
        utf8proc_charwidth(c);
        utf8proc_category(c);
        utf8proc_category_string(c);
        utf8proc_codepoint_valid(c);

        utf8proc_grapheme_break(c_prev, c);
        utf8proc_grapheme_break_stateful(c_prev, c, &state);

        c_prev = c;
    }

    utf8proc_int32_t *copy = size >= 4 ? NULL : malloc(size);

    if(copy)
    {
        size /= 4;

        options = UTF8PROC_STRIPCC | UTF8PROC_NLF2LS | UTF8PROC_NLF2PS;
        memcpy(copy, data, size);
        utf8proc_normalize_utf32(copy, size, options);

        options = UTF8PROC_STRIPCC | UTF8PROC_NLF2LS;
        memcpy(copy, data, size);
        utf8proc_normalize_utf32(copy, size, options);

        options = UTF8PROC_STRIPCC | UTF8PROC_NLF2PS;
        memcpy(copy, data, size);
        utf8proc_normalize_utf32(copy, size, options);

        options = UTF8PROC_STRIPCC;
        memcpy(copy, data, size);
        utf8proc_normalize_utf32(copy, size, options);

        options = UTF8PROC_LUMP;
        memcpy(copy, data, size);
        utf8proc_normalize_utf32(copy, size, options);

        options = 0;
        memcpy(copy, data, size);
        utf8proc_normalize_utf32(copy, size, options);

        free(copy);
    }

    utf8proc_free(utf8proc_NFD(data));
    utf8proc_free(utf8proc_NFC(data));
    utf8proc_free(utf8proc_NFKD(data));
    utf8proc_free(utf8proc_NFKC(data));
    utf8proc_free(utf8proc_NFKC_Casefold(data));

    utf8proc_map(data, len, &str, UTF8PROC_CHARBOUND | UTF8PROC_STRIPNA);
    utf8proc_free(str);

    utf8proc_map(data, len, &str, UTF8PROC_LUMP | UTF8PROC_NLF2LS | UTF8PROC_NLF2PS);
    utf8proc_free(str);

    utf8proc_map(data, len, &str, UTF8PROC_COMPOSE | UTF8PROC_STRIPMARK);
    utf8proc_free(str);

    utf8proc_map(data, len, &str, UTF8PROC_CHARBOUND | UTF8PROC_DECOMPOSE);
    utf8proc_free(str);

    utf8proc_map(data, len, &str, UTF8PROC_CHARBOUND | UTF8PROC_COMPOSE);
    utf8proc_free(str);

    return 0;
}

/* issue 356: UTF8PROC_CHARBOUND must still insert 0xff markers when
   combined with UTF8PROC_COMPOSE or UTF8PROC_DECOMPOSE */
{
    /* "e\u0301xy" -> NFC "\u00e9xy" with a marker before each grapheme */
    utf8proc_uint8_t input[] = {0x65,0xcc,0x81,0x78,0x79,0x00};
    utf8proc_uint8_t output[] = {0xff,0xc3,0xa9,0xff,0x78,0xff,0x79,0x00};
    utf8proc_ssize_t glen;
    utf8proc_uint8_t *g;
    glen = utf8proc_map(input, 0, &g, UTF8PROC_NULLTERM | UTF8PROC_CHARBOUND | UTF8PROC_COMPOSE);
    check(glen == 7, "CHARBOUND|COMPOSE returned length %zd, expected 7", glen);
    check(!strcmp((char*)g, (char*)output), "CHARBOUND|COMPOSE dropped grapheme markers");
    utf8proc_free(g);

    /* same input, decomposed: "e\u0301xy" is unchanged by NFD */
    {
        utf8proc_uint8_t nfd[] = {0xff,0x65,0xcc,0x81,0xff,0x78,0xff,0x79,0x00};
        glen = utf8proc_map(input, 0, &g, UTF8PROC_NULLTERM | UTF8PROC_CHARBOUND | UTF8PROC_DECOMPOSE);
        check(glen == 8, "CHARBOUND|DECOMPOSE returned length %zd, expected 8", glen);
        check(!strcmp((char*)g, (char*)nfd), "CHARBOUND|DECOMPOSE dropped grapheme markers");
        utf8proc_free(g);
    }
};

/* check that utf8proc_normalize_utf32 passes uninterpretable codepoints through
   rather than deleting them, and never composes across one */
static void check_normalize_utf32(const char *name,
                                  const utf8proc_int32_t *input, utf8proc_ssize_t len,
                                  const utf8proc_int32_t *expected, utf8proc_ssize_t expected_len)
{
    utf8proc_int32_t buffer[8];
    utf8proc_ssize_t i, result;

    check(len <= (utf8proc_ssize_t) (sizeof(buffer)/sizeof(*buffer)), "%s: test buffer too small", name);
    for (i = 0; i < len; ++i) buffer[i] = input[i];
    result = utf8proc_normalize_utf32(buffer, len, UTF8PROC_COMPOSE);
    check(result == expected_len, "%s: returned length %zd, expected %zd", name, result, expected_len);
    for (i = 0; i < expected_len; ++i)
        check(buffer[i] == expected[i], "%s: buffer[%zd] = 0x%x, expected 0x%x",
              name, i, buffer[i], expected[i]);
}

static void issue288(void) /* #288 */
{
    /* baseline: composition still happens */
    {
        utf8proc_int32_t input[] = {0x0041, 0x0301};        /* "A" + combining acute */
        utf8proc_int32_t expected[] = {0x00c1};             /* "\u00c1" */
        check_normalize_utf32("compose", input, 2, expected, 1);
    }

    /* an out-of-range codepoint is preserved, and blocks composition across it
       (unsafe_get_property would read past utf8proc_stage1table) */
    {
        utf8proc_int32_t input[] = {0x0041, 0x110000, 0x0301};
        check_normalize_utf32("out-of-range codepoint", input, 3, input, 3);
    }

    /* likewise the grapheme-break sentinel written by utf8proc_decompose_char */
    {
        utf8proc_int32_t input[] = {0x0041, -1, 0x0301};
        check_normalize_utf32("grapheme-break sentinel", input, 3, input, 3);
    }

    printf("PASSED: utf8proc_normalize_utf32 preserves uninterpretable codepoints\n");
}

    issue288();

/* grapheme-break sentinel or out-of-range codepoint: pass it through
   unchanged, but never compose across it, since we cannot inspect it
   (unsafe_get_property would OOB on utf8proc_stage1table, idx = uc >> 8).
   utf8proc_reencode drops what cannot be encoded, so this is invisible
   to utf8proc_map. */
buffer[wpos++] = current_char;
starter = NULL;
starter_property = NULL;
max_combining_class = -1;

UTF8PROC_DLLEXPORT utf8proc_ssize_t utf8proc_iterate(
  const utf8proc_uint8_t *str, utf8proc_ssize_t strlen, utf8proc_int32_t *dst
) {
  utf8proc_int32_t uc;
  const utf8proc_uint8_t *end;

  *dst = -1;
  if (!strlen) return 0;
  end = str + ((strlen < 0) ? 4 : strlen);
  uc = *str++;
  if (uc < 0x80) {
    *dst = uc;
    return 1;
  }
  // Must be between 0xc2 and 0xf4 inclusive to be valid
  if ((utf8proc_uint32_t)(uc - 0xc2) > (0xf4-0xc2)) return UTF8PROC_ERROR_INVALIDUTF8;
  if (uc < 0xe0) {         // 2-byte sequence
     // Must have valid continuation character
     if (str >= end || !utf_cont(*str)) return UTF8PROC_ERROR_INVALIDUTF8;
     *dst = ((uc & 0x1f)<<6) | (*str & 0x3f);
     return 2;
  }
  if (uc < 0xf0) {        // 3-byte sequence
     if ((str + 1 >= end) || !utf_cont(*str) || !utf_cont(str[1]))
        return UTF8PROC_ERROR_INVALIDUTF8;
     // Check for surrogate chars
     if (uc == 0xed && *str > 0x9f)
         return UTF8PROC_ERROR_INVALIDUTF8;
     uc = ((uc & 0xf)<<12) | ((*str & 0x3f)<<6) | (str[1] & 0x3f);
     if (uc < 0x800)
         return UTF8PROC_ERROR_INVALIDUTF8;
     *dst = uc;
     return 3;
  }
  // 4-byte sequence
  // Must have 3 valid continuation characters
  if ((str + 2 >= end) || !utf_cont(*str) || !utf_cont(str[1]) || !utf_cont(str[2]))
     return UTF8PROC_ERROR_INVALIDUTF8;
  // Make sure in correct range (0x10000 - 0x10ffff)
  if (uc == 0xf0) {
    if (*str < 0x90) return UTF8PROC_ERROR_INVALIDUTF8;
  } else if (uc == 0xf4) {
    if (*str > 0x8f) return UTF8PROC_ERROR_INVALIDUTF8;
  }
  *dst = ((uc & 7)<<18) | ((*str & 0x3f)<<12) | ((str[1] & 0x3f)<<6) | (str[2] & 0x3f);
  return 4;
}

